class ThemeSwitch{setTheme=e=>{document.querySelector("html").setAttribute("data-bs-theme",e),localStorage.setItem("theme",e),"dark"===e&&this.updateSwitches(e)};getTheme=function(){return localStorage.getItem("theme")||"light"};toggleTheme=()=>{let e="dark"===this.getTheme()?"light":"dark";this.setTheme(e)};updateSwitches=e=>{const t=document.querySelectorAll("[data-bs-theme-switch]");for(const h of t)h.checked="dark"===e}}document.addEventListener("DOMContentLoaded",()=>{const e=new ThemeSwitch;e.setTheme(e.getTheme())}),document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll("[data-bs-theme-switch]");for(const t of e)t.addEventListener("change",()=>{const e=new ThemeSwitch;t.checked?e.setTheme("dark"):e.setTheme("light")})});